def f(g):
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]
    dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0: dq.append((i,j)); seen[i][j]=True
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and not seen[i][j]: dq.append((i,j)); seen[i][j]=True
    while dq:
        i,j=dq.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==0 and not seen[a][b]:
                seen[a][b]=True; dq.append((a,b))
    return [[2 if g[i][j]==0 and not seen[i][j] else g[i][j] for j in range(w)] for i in range(h)]
